#ifndef __PSEUDORANDOMTESTS_H__
#define __PSEUDORANDOMTESTS_H__

#include "IEcoBase1.h"
#include "ErrEcoCodes.h"
#include "IEcoPseudoRandomService1.h"
#include "IEcoPseudoRandom1.h"

#define PRNG_STEPS 10
#define ECO_U64(hi, lo) ((((uint64_t)(hi)) << 32) | ((uint64_t)(lo)))
static unsigned long g_PRNGChecks = 0;
#define PRNG_CHECK(cond) do { ++n; ++g_PRNGChecks; if (!(cond)) { return n; } } while (0)

typedef struct PRNGCase32 {
    uint32_t seed;
    uint32_t param;
    uint32_t expected[PRNG_STEPS];
} PRNGCase32;

typedef struct PRNGCase64 {
    uint64_t seed;
    uint64_t param;
    uint64_t expected[PRNG_STEPS];
} PRNGCase64;

#include "PRNGVectors.h"

/* SOA: stateless service */
static int16_t PRNGTestService(IEcoPseudoRandomService1* pS) {
    int16_t n = 0;
    int16_t res = 0;
    uint32_t i = 0;
    uint32_t j = 0;
    uint32_t out32 = 0;
    uint64_t out64 = 0;
    uint32_t s32 = 0;
    uint64_t s64 = 0;

    for (i = 0; i < PRNG_CASES32; i++) {
        s32 = g_Cases32[i].seed;
        for (j = 0; j < PRNG_STEPS; j++) {
            res = pS->pVTbl->Step32(pS, s32, g_Cases32[i].param, &out32);
            PRNG_CHECK(res == ERR_ECO_SUCCESS);
            PRNG_CHECK(out32 == g_Cases32[i].expected[j]);
            s32 = out32;
        }
    }
    for (i = 0; i < PRNG_CASES64; i++) {
        s64 = g_Cases64[i].seed;
        for (j = 0; j < PRNG_STEPS; j++) {
            res = pS->pVTbl->Step64(pS, s64, g_Cases64[i].param, &out64);
            PRNG_CHECK(res == ERR_ECO_SUCCESS);
            PRNG_CHECK(out64 == g_Cases64[i].expected[j]);
            s64 = out64;
        }
    }

    /* zero state, NULL pointers */
    PRNG_CHECK(pS->pVTbl->Step32(pS, 0, 0, &out32) == ERR_ECO_INVALIDARG);
    PRNG_CHECK(pS->pVTbl->Step64(pS, 0, 0, &out64) == ERR_ECO_INVALIDARG);
    PRNG_CHECK(pS->pVTbl->Step32(pS, 1, 0, 0) == ERR_ECO_POINTER);
    PRNG_CHECK(pS->pVTbl->Step64(pS, 1, 0, 0) == ERR_ECO_POINTER);
    PRNG_CHECK(pS->pVTbl->Step32(0, 1, 0, &out32) == ERR_ECO_POINTER);
    PRNG_CHECK(pS->pVTbl->Step64(0, 1, 0, &out64) == ERR_ECO_POINTER);

#if PRNG_HAS_MASK
    /* state is zero inside the 16 bit register defined by the mask */
    PRNG_CHECK(pS->pVTbl->Step32(pS, 0x10000UL, 0xB400UL, &out32) == ERR_ECO_INVALIDARG);

    /* maximal period of the 16 bit register is 65535 */
    s32 = 1;
    for (i = 1; i <= 65535UL; i++) {
        res = pS->pVTbl->Step32(pS, s32, 0xB400UL, &out32);
        PRNG_CHECK(res == ERR_ECO_SUCCESS);
        s32 = out32;
        if (i < 65535UL && s32 == 1) {
            PRNG_CHECK(0);
        }
    }
    PRNG_CHECK(s32 == 1);
#endif
    return 0;
}

/* OOA: stateful object. pO is initialized by the caller; pFresh is a new, never initialized object. */
static int16_t PRNGTestObject(IEcoPseudoRandom1* pO, IEcoPseudoRandom1* pFresh) {
    int16_t n = 0;
    int16_t res = 0;
    uint32_t i = 0;
    uint32_t j = 0;
    uint64_t out = 0;
    uint64_t first = 0;
    char_t* name = 0;

    PRNG_CHECK(pFresh->pVTbl->Next(pFresh, &out) == ERR_ECO_FAIL);

    for (i = 0; i < PRNG_CASES32; i++) {
        res = pO->pVTbl->Init(pO, g_Cases32[i].seed, g_Cases32[i].param, 32);
        PRNG_CHECK(res == ERR_ECO_SUCCESS);
        for (j = 0; j < PRNG_STEPS; j++) {
            res = pO->pVTbl->Next(pO, &out);
            PRNG_CHECK(res == ERR_ECO_SUCCESS);
            PRNG_CHECK(out == (uint64_t)g_Cases32[i].expected[j]);
        }
    }
    for (i = 0; i < PRNG_CASES64; i++) {
        res = pO->pVTbl->Init(pO, g_Cases64[i].seed, g_Cases64[i].param, 64);
        PRNG_CHECK(res == ERR_ECO_SUCCESS);
        for (j = 0; j < PRNG_STEPS; j++) {
            res = pO->pVTbl->Next(pO, &out);
            PRNG_CHECK(res == ERR_ECO_SUCCESS);
            PRNG_CHECK(out == g_Cases64[i].expected[j]);
        }
    }

    /* re-Init restarts the sequence */
    PRNG_CHECK(pO->pVTbl->Init(pO, g_Cases32[0].seed, g_Cases32[0].param, 32) == ERR_ECO_SUCCESS);
    PRNG_CHECK(pO->pVTbl->Next(pO, &first) == ERR_ECO_SUCCESS);
    PRNG_CHECK(first == (uint64_t)g_Cases32[0].expected[0]);

    /* invalid arguments */
    PRNG_CHECK(pO->pVTbl->Init(pO, 0, 0, 32) == ERR_ECO_INVALIDARG);
    PRNG_CHECK(pO->pVTbl->Init(pO, 0, 0, 64) == ERR_ECO_INVALIDARG);
    PRNG_CHECK(pO->pVTbl->Init(pO, 1, 0, 16) == ERR_ECO_INVALIDARG);
    PRNG_CHECK(pO->pVTbl->Init(pO, 1, 0, 0) == ERR_ECO_INVALIDARG);
    PRNG_CHECK(pO->pVTbl->Init(0, 1, 0, 32) == ERR_ECO_POINTER);
    PRNG_CHECK(pO->pVTbl->Next(pO, 0) == ERR_ECO_POINTER);
    PRNG_CHECK(pO->pVTbl->Next(0, &out) == ERR_ECO_POINTER);

    name = pO->pVTbl->get_Name(pO);
    PRNG_CHECK(name != 0);
    PRNG_CHECK(name[0] != 0);
    return 0;
}

/* Rules of QueryInterface / AddRef / Release from lecture 3 */
static const UGUID IID_PRNGUnsupported = {0x01, 0x10, {0xDE, 0xAD, 0xBE, 0xEF, 0x00, 0x00, 0x40, 0x00, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01}};

static int16_t PRNGTestIdentity(IEcoPseudoRandomService1* pS) {
    int16_t n = 0;
    IEcoUnknown* pU1 = 0;
    IEcoUnknown* pU2 = 0;
    IEcoPseudoRandom1* pO = 0;
    IEcoPseudoRandomService1* pS2 = 0;
    IEcoPseudoRandomService1* pS3 = 0;
    voidptr_t pBad = (voidptr_t)pS;
    uint32_t r1 = 0;
    uint32_t r2 = 0;

    /* both interfaces belong to one component and give the same IEcoUnknown */
    PRNG_CHECK(pS->pVTbl->QueryInterface(pS, &IID_IEcoPseudoRandom1, (voidptr_t*)&pO) == ERR_ECO_SUCCESS);
    PRNG_CHECK(pO != 0);
    PRNG_CHECK(pS->pVTbl->QueryInterface(pS, &IID_IEcoUnknown, (voidptr_t*)&pU1) == ERR_ECO_SUCCESS);
    PRNG_CHECK(pO->pVTbl->QueryInterface(pO, &IID_IEcoUnknown, (voidptr_t*)&pU2) == ERR_ECO_SUCCESS);
    PRNG_CHECK(pU1 == pU2);

    /* we can always return to where we started, and re-query what we already have */
    PRNG_CHECK(pO->pVTbl->QueryInterface(pO, &IID_IEcoPseudoRandomService1, (voidptr_t*)&pS2) == ERR_ECO_SUCCESS);
    PRNG_CHECK(pS2 == pS);
    PRNG_CHECK(pS->pVTbl->QueryInterface(pS, &IID_IEcoPseudoRandomService1, (voidptr_t*)&pS3) == ERR_ECO_SUCCESS);
    PRNG_CHECK(pS3 == pS);

    /* unsupported interface: error code and NULL result */
    PRNG_CHECK(pS->pVTbl->QueryInterface(pS, &IID_PRNGUnsupported, &pBad) == ERR_ECO_NOINTERFACE);
    PRNG_CHECK(pBad == 0);
    PRNG_CHECK(pS->pVTbl->QueryInterface(pS, &IID_IEcoUnknown, 0) == ERR_ECO_POINTER);
    PRNG_CHECK(pS->pVTbl->QueryInterface(0, &IID_IEcoUnknown, (voidptr_t*)&pU1) == ERR_ECO_POINTER);

    /* reference counting: every successful QueryInterface added one reference */
    r1 = pS->pVTbl->AddRef(pS);
    r2 = pS->pVTbl->Release(pS);
    PRNG_CHECK(r1 == r2 + 1);

    pU1->pVTbl->Release(pU1);
    pU2->pVTbl->Release(pU2);
    pO->pVTbl->Release(pO);
    pS2->pVTbl->Release(pS2);
    pS3->pVTbl->Release(pS3);
    return 0;
}

#endif /* __PSEUDORANDOMTESTS_H__ */
